{
  "passageId": "surface-tension-laplace",
  "itemKey": "b",
  "form": "BOGI",
  "situation": {
    "description": "잉크젯 프린터의 네 가지 설정을 비교하여, 표면 장력이나 점도를 바꾼 두 설정의 오네소르게 수와 인쇄 결과를 판단하는 상황.",
    "slotRef": null,
    "bogiText": "잉크젯 프린터의 설정 A에서 오네소르게 수를 측정하였더니 0.05였다. 설정 B는 A와 잉크의 점도·밀도 및 노즐 지름이 같고, 잉크의 표면 장력만 A의 두 배이다. 별도의 설정 C에서 오네소르게 수는 2.0으로 측정되었다. 설정 D는 C와 잉크의 표면 장력·밀도 및 노즐 지름이 같고, 잉크의 점도만 C의 두 배이다."
  },
  "usedRuleIds": [
    "R5",
    "R6"
  ],
  "steps": [
    {
      "n": 1,
      "given": "A의 오네소르게 수는 0.05이다. B는 A와 점도·밀도·노즐 지름이 같고 표면 장력만 두 배이다.",
      "ruleId": "R5",
      "ruleQuote": "오네소르게 수는 잉크의 점도가 클수록 크고, 잉크의 표면 장력, 잉크의 밀도, 노즐의 지름, 이 세 값의 곱이 클수록 작다.",
      "result": "B에서는 표면 장력·밀도·노즐 지름의 곱이 A의 두 배가 되므로, B의 오네소르게 수는 0.05보다 작다."
    },
    {
      "n": 2,
      "given": "1단계에서 B의 오네소르게 수가 0.05보다 작으므로, 안정적인 인쇄 범위의 하한인 약 0.1보다도 작다.",
      "ruleId": "R6",
      "ruleQuote": "일반적으로 오네소르게 수의 범위가 대략 0.1에서 1.0 사이이면 안정적인 인쇄가 가능하다. 가령 점도가 커서 오네소르게 수가 이 범위보다 크게 되면 잉크가 노즐 밖으로 나오지 못한다. 이와 반대의 경우, 수많은 위성 잉크 방울이 생겨 원치 않는 오염이 발생한다.",
      "result": "B에서는 수많은 위성 잉크 방울이 생겨 원치 않는 오염이 발생한다."
    },
    {
      "n": 3,
      "given": "C의 오네소르게 수는 2.0이다. D는 C와 표면 장력·밀도·노즐 지름이 같고 점도만 두 배이다.",
      "ruleId": "R5",
      "ruleQuote": "오네소르게 수는 잉크의 점도가 클수록 크고, 잉크의 표면 장력, 잉크의 밀도, 노즐의 지름, 이 세 값의 곱이 클수록 작다.",
      "result": "D에서는 표면 장력·밀도·노즐 지름의 곱이 일정한 채 점도만 커지므로, D의 오네소르게 수는 2.0보다 크다."
    },
    {
      "n": 4,
      "given": "3단계에서 D의 오네소르게 수가 2.0보다 크므로, 안정적인 인쇄 범위의 상한인 약 1.0보다도 크다.",
      "ruleId": "R6",
      "ruleQuote": "일반적으로 오네소르게 수의 범위가 대략 0.1에서 1.0 사이이면 안정적인 인쇄가 가능하다. 가령 점도가 커서 오네소르게 수가 이 범위보다 크게 되면 잉크가 노즐 밖으로 나오지 못한다. 이와 반대의 경우, 수많은 위성 잉크 방울이 생겨 원치 않는 오염이 발생한다.",
      "result": "D에서는 잉크가 노즐 밖으로 나오지 못한다."
    }
  ],
  "derivedFacts": [
    {
      "id": "F1",
      "text": "B의 오네소르게 수는 A에서 측정된 0.05보다 작다.",
      "fromSteps": [
        1
      ],
      "ifDifferent": "B의 표면 장력이 A의 절반이고 나머지 조건이 같았다면, B의 오네소르게 수는 0.05보다 커졌을 것이다."
    },
    {
      "id": "F2",
      "text": "B에서는 위성 잉크 방울로 인한 오염이 발생한다.",
      "fromSteps": [
        1,
        2
      ],
      "ifDifferent": "B의 오네소르게 수가 0.5로 측정되는 조건이었다면, 위성 잉크 방울로 인한 오염이 아니라 안정적인 인쇄가 가능한 경우로 판단했을 것이다."
    },
    {
      "id": "F3",
      "text": "D의 오네소르게 수는 C에서 측정된 2.0보다 크다.",
      "fromSteps": [
        3
      ],
      "ifDifferent": "D의 점도가 C의 절반이고 나머지 조건이 같았다면, D의 오네소르게 수는 2.0보다 작아졌을 것이다."
    },
    {
      "id": "F4",
      "text": "D에서는 점도를 높인 결과 잉크가 노즐 밖으로 나오지 못하는 상태가 유지된다.",
      "fromSteps": [
        3,
        4
      ],
      "ifDifferent": "D의 오네소르게 수가 0.5가 되는 조건이었다면, 잉크가 노즐 밖으로 나오지 못하는 경우가 아니라 안정적인 인쇄가 가능한 경우로 판단했을 것이다."
    }
  ],
  "selfCheck": "다른 요인이 고정된 상태에서 표면 장력과 점도의 변화 방향만으로 B와 D의 오네소르게 수의 대소를 판단했으며, 지문에 없는 정확한 배율 관계는 사용하지 않았다. 두 결과가 각각 0.1 미만과 1.0 초과임이 확실하므로, 위성 잉크 방울 발생과 노즐 배출 불가라는 결론이 규칙에서 바로 도출된다."
}

